// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    // allow c to transfer Ether back to us (owner == this contract)
    receive() external payable {}

    function testFuzz_property(uint256 fundAmt, uint256 v, address funder) public {
        vm.assume(fundAmt <= VALUE_CAP);
        vm.assume(funder != address(c) && funder != address(this));
        fundAmt = bound(fundAmt, 1, 100 ether);

        // fund c through its payable fallback with a fuzzed amount
        vm.deal(funder, fundAmt);
        vm.prank(funder);
        (bool okFund, ) = address(c).call{value: fundAmt}("");
        assertTrue(okFund);

        // withdraw a fuzzed amount not exceeding the balance (admissible domain)
        uint256 balBefore = address(c).balance;
        v = bound(v, 0, balBefore);
        // only inputs with v < B distinguish the two versions
        vm.assume(v < balBefore);

        vm.prank(address(this)); // owner
        c.withdraw(v);

        // exactly v wei must have left the contract
        assertTrue(address(c).balance == balBefore - v);
    }
}
